import itertools

CONDITION_LABELS = [
    "H_1: I is a proper ideal of R",
    "H_2: f is a polynomial over R",
    "H_3: J is the ideal generated by I and f",
    "H_4: f_bar is the image of f under the natural projection",
    "neg_Q: The factor rings are NOT isomorphic"
]

N_HYP = 4
NEG_Q_INDEX = 4

def conditions(witness):
    try:
        R_size = witness['R_size']
        add = witness['add']
        mul = witness['mul']
        I = witness['I']
        f = witness['f']
        
        # Find zero element
        zero_idx = None
        for i in range(R_size):
            if all(add[i][j] == j and add[j][i] == j for j in range(R_size)):
                zero_idx = i
                break
                
        I_set = set(I)
        
        h1 = True
        if zero_idx is None or zero_idx not in I_set:
            h1 = False
        if len(I_set) >= R_size or len(I_set) == 0:
            h1 = False
        for a in I_set:
            for b in I_set:
                if add[a][b] not in I_set:
                    h1 = False
        for r in range(R_size):
            for a in I_set:
                if mul[r][a] not in I_set or mul[a][r] not in I_set:
                    h1 = False
                    
        h2 = True
        if not isinstance(f, list) or len(f) == 0:
            h2 = False
        else:
            for c in f:
                if c < 0 or c >= R_size:
                    h2 = False
                    
        h3 = True
        h4 = True
        
        neg_q = False
        
        if h1 and h2:
            D = 2
            
            def poly_add(p1, p2):
                return tuple(add[p1[i]][p2[i]] for i in range(D+1))
                
            def additive_closure(gen_list):
                closure = set()
                zero_poly = tuple([zero_idx]*(D+1))
                closure.add(zero_poly)
                
                queue = [zero_poly]
                idx = 0
                while idx < len(queue):
                    curr = queue[idx]
                    idx += 1
                    for g in gen_list:
                        nxt = poly_add(curr, g)
                        if nxt not in closure:
                            closure.add(nxt)
                            queue.append(nxt)
                return closure

            I_coeffs_J = []
            I_coeffs_J.append(list(I_set))
            
            coeffs_k = set()
            for a in range(R_size):
                for c in I_set:
                    coeffs_k.add(mul[a][c])
                    coeffs_k.add(mul[c][a])
                    for b in range(R_size):
                        coeffs_k.add(mul[mul[a][c]][b])
                        
            closure_k = set([zero_idx])
            queue = list(closure_k)
            idx = 0
            while idx < len(queue):
                curr = queue[idx]
                idx += 1
                for g in coeffs_k:
                    nxt = add[curr][g]
                    if nxt not in closure_k:
                        closure_k.add(nxt)
                        queue.append(nxt)
                        
            for k in range(1, D+1):
                I_coeffs_J.append(list(closure_k))
                
            I_coeffs_K = [list(I_set) for _ in range(D+1)]
            
            f_gens = []
            if f:
                p = [zero_idx]*(D+1)
                for i in range(min(len(f), D+1)):
                    p[i] = f[i]
                f_gens.append(tuple(p))
                
                for a in range(R_size):
                    for i in range(D+1):
                        p = [zero_idx]*(D+1)
                        for k in range(i, D+1):
                            if k - i < len(f):
                                p[k] = mul[a][f[k-i]]
                        f_gens.append(tuple(p))
                        
                for b in range(R_size):
                    for j in range(D+1):
                        p = [zero_idx]*(D+1)
                        for k in range(j, D+1):
                            if k - j < len(f):
                                p[k] = mul[f[k-j]][b]
                        f_gens.append(tuple(p))
                        
                for a in range(R_size):
                    for b in range(R_size):
                        for i in range(D+1):
                            for j in range(D+1 - i):
                                p = [zero_idx]*(D+1)
                                for k in range(i+j, D+1):
                                    if k - i - j < len(f):
                                        p[k] = mul[mul[a][f[k-i-j]]][b]
                                f_gens.append(tuple(p))
                                
            Gen_J = list(f_gens)
            for k in range(D+1):
                for c in I_coeffs_J[k]:
                    p = [zero_idx]*(D+1)
                    p[k] = c
                    Gen_J.append(tuple(p))
                    
            Gen_K = list(f_gens)
            for k in range(D+1):
                for c in I_coeffs_K[k]:
                    p = [zero_idx]*(D+1)
                    p[k] = c
                    Gen_K.append(tuple(p))
                    
            zero_poly = tuple([zero_idx]*(D+1))
            Gen_J = list(set(Gen_J) - {zero_poly})
            Gen_K = list(set(Gen_K) - {zero_poly})
            
            J_D = additive_closure(Gen_J)
            K_D = additive_closure(Gen_K)
            
            if J_D != K_D:
                neg_q = True
                
        return [h1, h2, h3, h4, neg_q]
    except Exception:
        return [False, False, False, False, False]